"""Weld corresponding chart vertices without collapsing small neighboring cells.

Integer chart keys identify mouth profiles, inner-sector curves and center rays.
Interior vertices receive unique keys. Merge By Distance operates in this key
space; the captured physical position is restored afterwards. No triangles are
created first, and unrelated nearby physical positions never define identity.
"""
from .backend_runtime import V, choose, named, remove


def edge(g, parameter, high=False):
    return g.math('GREATER_THAN', parameter, .9999999) if high else g.math('LESS_THAN', parameter, .0000001)


def tag(g, geometry, key, selection, mouth):
    geometry=g.store(geometry, '_chart_key', key, 'POINT', 'FLOAT_VECTOR')
    geometry=g.store(geometry, '_chart_shared', selection, 'POINT', 'BOOLEAN')
    return g.store(geometry, 'st_mouth_vertex', mouth, 'POINT', 'BOOLEAN')


def patch(g, geometry, patch, arms, raw, v, radial, q, plateau, factor, rm):
    sector=rm.equal(g,patch('kind','INT'),1)
    nu=patch('nu_base')*factor
    nv=patch('nv_base')*factor
    first, last=edge(g,raw),edge(g,raw,True)
    crown=edge(g,radial)
    inner=g.xyz(1.,patch('sector_index','INT'),g.math('ROUND',raw*nu))
    mouth=g.xyz(0.,choose(g,first,patch('first_arm','INT'),patch('second_arm','INT')),
        choose(g,first,-1.,1.)*g.math('ROUND',v*nv))
    sector_key=choose(g,g.math('MAXIMUM',first,last),mouth,inner,'VECTOR')
    sector_shared=g.math('MAXIMUM',crown,g.math('MAXIMUM',first,last))

    # Invert the quarter-row plateau sampling to the common full half-profile
    # lattice. Ordinary strips and divided strips use different radial counts.
    aq=g.math('ABSOLUTE',q)
    divided=g.math('GREATER_THAN',plateau,0.)
    fraction=choose(g,g.math('GREATER_THAN',aq,plateau),
        .25+.75*(aq-plateau)/(1.-plateau),.25*aq/plateau)
    fraction=choose(g,divided,fraction,aq)
    full_nv=choose(g,divided,nv/.75,nv)
    sign=choose(g,g.math('LESS_THAN',q,0.),-1.,1.)
    strip_mouth=g.xyz(0.,patch('arm','INT'),sign*g.math('ROUND',fraction*full_nv))
    strip_axis=g.xyz(4.,patch('arm','INT'),g.math('ROUND',raw*nu))
    axis=g.math('LESS_THAN',aq,1e-7)
    strip_key=choose(g,first,strip_mouth,strip_axis,'VECTOR')
    return tag(g,geometry,choose(g,sector,sector_key,strip_key,'VECTOR'),
        choose(g,sector,sector_shared,g.math('MAXIMUM',first,axis)),
        choose(g,sector,g.math('MAXIMUM',first,last),first))


def center(g, geometry, sectors, index, prev, factor, u, v, rm):
    count=rm.read(g,sectors,'nu_base',index)*factor
    half=count*.5
    u0,u1,v0,v1=edge(g,u),edge(g,u,True),edge(g,v),edge(g,v,True)
    key=g.xyz(2.,index,g.math('ROUND',v*half))
    key=choose(g,v1,g.xyz(2.,prev,g.math('ROUND',u*half)),key,'VECTOR')
    key=choose(g,u0,g.xyz(1.,prev,count-g.math('ROUND',v*half)),key,'VECTOR')
    key=choose(g,v0,g.xyz(1.,index,g.math('ROUND',u*half)),key,'VECTOR')
    key=choose(g,u0*v0,g.xyz(0.,rm.read(g,sectors,'first_arm',index,'INT'),0.),key,'VECTOR')
    key=choose(g,u1*v1,g.xyz(3.,0.,0.),key,'VECTOR')
    return tag(g,geometry,key,g.math('MAXIMUM',g.math('MAXIMUM',u0,u1),g.math('MAXIMUM',v0,v1)),u0*v0)


def weld(g, geometry):
    geometry=g.store(geometry,'_chart_position',g.position(),'POINT','FLOAT_VECTOR')
    index=V(g,g.node('GeometryNodeInputIndex').outputs['Index'])
    key=choose(g,named(g,'_chart_shared','BOOLEAN'),named(g,'_chart_key','FLOAT_VECTOR'),g.xyz(-1.,index,0.),'VECTOR')
    geometry=g.setpos(geometry,key)
    node=g.node('GeometryNodeMergeByDistance','Weld matching integer chart coordinates only')
    node.inputs['Distance'].default_value=.1
    g.bind(geometry,node.inputs['Geometry'])
    nearest=g.node('GeometryNodeSampleNearest','Find the merged integer identity');nearest.domain='POINT'
    g.bind(node.outputs['Geometry'],nearest.inputs['Geometry'])
    g.bind(g.position(),nearest.inputs['Sample Position'])
    sample=g.node('GeometryNodeSampleIndex','Physical position of this verified chart identity')
    sample.data_type='FLOAT_VECTOR';sample.domain='POINT'
    g.bind(node.outputs['Geometry'],sample.inputs['Geometry'])
    g.bind(named(g,'_chart_position','FLOAT_VECTOR'),sample.inputs['Value'])
    g.bind(nearest.outputs['Index'],sample.inputs['Index'])
    a=g.separate(named(g,'_chart_position','FLOAT_VECTOR'))
    b=g.separate(V(g,sample.outputs['Value']))
    error=g.math('SQRT',sum((x-y)**2 for x,y in zip(a,b)))
    stat=g.node('GeometryNodeAttributeStatistic','Maximum physical disagreement before chart welding')
    stat.domain='POINT';stat.data_type='FLOAT'
    g.bind(geometry,stat.inputs['Geometry']);g.bind(error,stat.inputs['Attribute'])
    size=g.node('GeometryNodeAttributeDomainSize','Exact integer identity budget');size.component='MESH'
    g.bind(geometry,size.inputs['Geometry'])
    valid=g.math('LESS_THAN',V(g,stat.outputs['Max']),1e-5)*g.math('LESS_THAN',V(g,size.outputs['Point Count']),2**24)
    geometry=g.store(node.outputs['Geometry'],'_chart_seam_ok',valid,'POINT','BOOLEAN')
    geometry=g.setpos(geometry,named(g,'_chart_position','FLOAT_VECTOR'))
    for attr in ('_chart_position','_chart_key','_chart_shared'):
        geometry=remove(g,geometry,attr)
    return geometry
